css:
:host { --paper: #f5f4ef; --ink: #24212c; --muted: #777180; --violet: #621ff8; --gold: #ffd12a; --cyan: #86f1ff; --night: #100d18; --rule: #d8d4df; }
* { box-sizing: border-box; }
body { margin: 0px; background: rgb(222, 220, 226); color: var(--ink); font-family: "PingFang SC", "Microsoft YaHei", sans-serif; -webkit-font-smoothing: antialiased; }
button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; cursor: pointer; }
button:focus-visible, a:focus-visible { outline: rgb(169, 138, 255) solid 3px; outline-offset: 5px; }
button:disabled { opacity: 0.3; cursor: default; }
figure, p, h1, h2, h3 { margin: 0px; }
em, i { font-style: normal; }
svg { display: block; width: 100%; height: 100%; font-family: inherit; }
#viewport { height: calc(100dvh - 66px); display: flex; align-items: center; justify-content: center; overflow: hidden; }
#stage { position: relative; width: 1920px; height: 1080px; flex-shrink: 0; transform-origin: center center; }
.slide { position: absolute; inset: 0px; display: none; overflow: hidden; }
.slide.active { display: block; }
.light { background: var(--paper); }
.dark { background: var(--night); color: rgb(249, 247, 255); }
.mast { position: absolute; top: 48px; left: 100px; right: 100px; display: flex; justify-content: space-between; font-size: 18px; color: rgb(120, 113, 127); letter-spacing: 0.8px; }
.mast i { margin: 0px 15px; color: rgb(181, 172, 191); }
.mast > span:last-child { font-size: 15px; letter-spacing: 2px; }
.dark .mast { color: rgb(169, 159, 187); }
.dark .mast i { color: rgb(97, 82, 109); }
header { position: absolute; top: 135px; left: 100px; right: 100px; }
.eyebrow { font-size: 20px; letter-spacing: 1px; color: var(--violet); display: flex; gap: 13px; align-items: center; }
.eyebrow b { width: 8px; height: 8px; border-radius: 50%; background: var(--gold); }
.dark .eyebrow { color: rgb(185, 154, 237); }
h2 { font-size: 60px; font-weight: 600; letter-spacing: -1px; line-height: 1.35; }
header h2 { margin: 14px 0px 15px; }
header > p:last-child:not(.eyebrow) { font-size: 24px; line-height: 1.6; color: rgb(129, 121, 135); }
.dark header > p:last-child:not(.eyebrow) { color: rgb(176, 165, 189); }
footer { position: absolute; left: 100px; right: 100px; bottom: 33px; display: flex; justify-content: space-between; border-top: 1px solid var(--rule); padding-top: 19px; font-size: 16px; line-height: 1.5; color: rgb(143, 132, 153); }
footer > span:last-child { flex-shrink: 0; margin-left: 40px; letter-spacing: 2px; }
.dark footer { border-color: rgba(255, 255, 255, 0.133); color: rgb(153, 140, 169); }
.hero-art, .closing-art { clip-path: inset(0px 0px 25px); }

.hero-art { position: absolute; right: -515px; top: 10px; height: 980px; width: 2410px; object-fit: cover; object-position: 54% center; }
.hero-veil { position: absolute; inset: 0px; background: linear-gradient(90deg, rgb(16, 13, 24) 0%, rgb(16, 13, 24) 26%, rgba(16, 13, 24, 0.875) 39%, rgba(16, 13, 24, 0) 68%), linear-gradient(0deg, rgb(16, 13, 24) 2%, rgba(16, 13, 24, 0) 37%); }
.hero-main { position: absolute; left: 100px; top: 190px; width: 1010px; }
.hero h1 { font-size: 99px; font-weight: 550; line-height: 1.35; letter-spacing: -3px; margin: 38px 0px 24px; }
.hero h1 span { color: rgb(223, 197, 255); }
.hero-sub { font-size: 29px; line-height: 1.8; color: rgb(208, 197, 220); }
.hero-credit { margin-top: 40px; border-left: 2px solid rgb(139, 95, 196); padding-left: 21px; }
.hero-credit span { font-size: 17px; color: rgb(148, 133, 165); display: block; margin-bottom: 9px; }
.hero-credit strong { font-size: 23px; font-weight: 400; }
.hero-caption { position: absolute; right: 100px; bottom: 227px; text-align: right; padding-right: 22px; border-right: 2px solid rgb(220, 198, 123); }
.hero-caption span { display: block; font-size: 17px; color: rgb(174, 155, 190); margin-bottom: 10px; }
.hero-caption b { display: block; font-size: 26px; font-weight: 400; margin-bottom: 10px; }
.hero-caption small { font-size: 18px; color: rgb(191, 176, 207); }
.hero-route { position: absolute; left: 100px; right: 100px; bottom: 137px; display: flex; align-items: center; gap: 42px; }
.hero-route > div { display: flex; align-items: center; gap: 18px; }
.hero-route em { font-family: Georgia, serif; font-size: 28px; color: rgb(150, 113, 194); }
.hero-route span { font-size: 25px; font-weight: 400; }
.hero-route > i { font-size: 26px; color: rgb(116, 101, 128); margin: 0px 15px; }
.attention-flow { position: absolute; top: 350px; left: 100px; right: 100px; display: grid; grid-template-columns: 1fr 62px 1fr 62px 1fr; }
.attention-flow article { padding: 0px 30px; }
.attention-flow article:first-child { padding-left: 0px; }
.attention-flow article:last-child { padding-right: 0px; }
.phase-label { display: flex; align-items: center; gap: 18px; }
.phase-label em { font-size: 44px; font-family: Georgia, serif; color: rgb(133, 97, 171); }
.phase-label span { font-size: 20px; color: rgb(150, 134, 159); }
.attention-diagram { height: 230px; margin: 6px 0px 7px; }
.attention-flow h3 { font-size: 35px; font-weight: 550; margin-bottom: 15px; }
.attention-flow article > p { font-size: 25px; line-height: 1.65; color: rgb(130, 114, 142); }
.phase-focus { display: flex; gap: 20px; align-items: center; border-top: 1px solid rgb(216, 204, 223); margin-top: 23px; padding-top: 19px; font-size: 19px; }
.phase-focus span { color: rgb(162, 147, 173); }
.phase-focus strong { font-weight: 400; color: rgb(84, 66, 95); }
.between-arrow { align-self: start; margin-top: 142px; color: rgb(176, 156, 192); font-size: 35px; text-align: center; }
.intent-bottom { position: absolute; left: 100px; right: 100px; top: 908px; display: flex; align-items: center; gap: 30px; padding-top: 20px; border-top: 1px solid var(--rule); font-size: 22px; }
.intent-bottom .context-label { font-size: 16px; color: rgb(150, 134, 159); margin-right: 12px; }
.intent-bottom small { font-size: 16px; color: rgb(149, 131, 159); margin-left: 14px; }
.intent-bottom i { color: rgb(186, 169, 198); }
.intent-bottom .context-current { color: var(--violet); }
.intent-bottom p { margin-left: auto; font-size: 18px; color: rgb(139, 122, 150); }
.sequence-layout { position: absolute; left: 100px; right: 100px; top: 322px; display: grid; grid-template-columns: 380px 1fr; gap: 60px; }
.sequence-steps { padding-top: 3px; }
.sequence-steps > button[role="tab"] { display: flex; align-items: center; gap: 18px; width: 100%; background: none; border-width: 0px 0px 1px; border-style: none none solid; border-color: currentcolor currentcolor rgba(255, 255, 255, 0.1); border-image: none; padding: 24px 12px 24px 0px; text-align: left; color: rgb(130, 116, 143); }
.sequence-steps em { font-family: Georgia, serif; font-size: 30px; flex-shrink: 0; }
.sequence-steps strong { display: block; font-size: 27px; font-weight: 500; }
.sequence-steps small { display: block; font-size: 17px; line-height: 1.6; margin-top: 8px; color: rgb(119, 103, 134); }
.sequence-steps button > i { margin-left: auto; font-size: 26px; }
.sequence-steps > button[aria-selected="true"] { color: rgb(255, 255, 255); border-bottom-color: rgb(154, 109, 230); }
.sequence-steps > button[aria-selected="true"] em, .sequence-steps > button[aria-selected="true"] > i { color: rgb(217, 183, 255); }
.sequence-steps > button[aria-selected="true"] small { color: rgb(187, 170, 202); }
.play-button { background: rgb(211, 185, 244); color: rgb(41, 23, 58); border: 0px; border-radius: 2px; padding: 14px 22px; margin-top: 29px; display: flex; gap: 14px; align-items: center; font-size: 20px; }
.play-button:hover { background: rgb(224, 201, 251); }
.sequence-disclaimer { font-size: 15px; line-height: 1.7; color: rgb(135, 116, 149); margin-top: 21px; }
.frame-window { height: 430px; position: relative; background: rgb(6, 3, 13); overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.098); }
.frame-window img { height: 100%; width: 100%; object-fit: cover; display: block; }
.frame-window img.changing { animation: 0.65s ease 0s 1 normal both running frame-in; }
@keyframes frame-in { 
  0% { opacity: 0.45; transform: scale(1.025); }
  100% { opacity: 1; transform: scale(1); }
}
.frame-label { position: absolute; left: 23px; top: 23px; font-size: 18px; color: rgb(231, 211, 255); border-left: 2px solid rgb(216, 180, 255); padding: 6px 13px; background: rgba(27, 16, 44, 0.79); }
.sequence-caption { display: flex; align-items: center; justify-content: space-between; height: 89px; gap: 24px; }
.sequence-caption p { font-size: 22px; color: rgb(203, 187, 218); max-width: 620px; line-height: 1.55; }
.sequence-caption > div { display: flex; gap: 8px; }
.sequence-caption span { font-size: 16px; white-space: nowrap; color: rgb(183, 160, 200); border: 1px solid rgb(81, 64, 92); padding: 6px 11px; }
.frame-strip { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; }
.frame-strip button { position: relative; background: rgb(8, 5, 14); border: 1px solid rgb(81, 64, 92); padding: 0px; height: 114px; overflow: hidden; }
.frame-strip img { width: 100%; height: 100%; object-fit: cover; opacity: 0.55; transition: opacity 0.2s; }
.frame-strip button.selected { border-color: rgb(211, 185, 244); box-shadow: rgb(211, 185, 244) 0px 0px 0px 1px; }
.frame-strip button.selected img, .frame-strip button:hover img { opacity: 1; }
.frame-strip span { position: absolute; bottom: 9px; left: 11px; font-size: 16px; color: rgb(255, 255, 255); text-shadow: rgb(0, 0, 0) 0px 1px 5px; background: rgba(23, 12, 36, 0.65); padding: 3px 8px; }
.retreat-layout { position: absolute; left: 100px; right: 100px; top: 347px; display: grid; grid-template-columns: 870px 1fr; gap: 80px; }
.retreat-frames figure { position: relative; }
.retreat-frames img { height: 241px; width: 100%; object-fit: cover; display: block; }
.retreat-frames figcaption { display: flex; align-items: center; gap: 13px; position: absolute; bottom: 13px; left: 18px; color: rgb(240, 231, 248); font-size: 17px; background: rgba(21, 13, 33, 0.85); padding: 7px 13px; }
.retreat-frames figcaption b { font-family: Georgia, serif; color: rgb(208, 172, 248); font-size: 21px; }
.transition-arrow { height: 60px; display: flex; align-items: center; justify-content: center; gap: 20px; color: rgb(144, 108, 169); font-size: 32px; }
.transition-arrow span { font-size: 18px; color: rgb(152, 133, 164); }
.layers-heading { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--rule); padding-bottom: 18px; }
.layers-heading > span { font-size: 23px; color: rgb(88, 67, 102); }
.layers-heading p { font-size: 17px; color: rgb(156, 133, 170); }
.layer-diagram { height: 280px; margin-top: 6px; }
.layer-notes > div { display: flex; align-items: center; border-bottom: 1px solid rgb(221, 212, 229); padding: 16px 0px; gap: 24px; }
.layer-notes em { font-size: 19px; font-family: Georgia, serif; color: rgb(176, 149, 191); }
.layer-notes h3 { font-size: 24px; font-weight: 400; }
.layer-notes span { margin-left: auto; color: rgb(148, 119, 167); font-size: 21px; }
.layer-notes > div:last-child span { color: rgb(98, 31, 248); }
.small-insight { display: flex; align-items: baseline; gap: 18px; font-size: 19px; line-height: 1.65; margin-top: 22px; color: rgb(138, 114, 152); }
.small-insight b { font-size: 16px; font-weight: 500; white-space: nowrap; color: rgb(94, 67, 109); }
.answer-layout { position: absolute; left: 100px; right: 100px; top: 353px; display: grid; grid-template-columns: 820px 1fr; gap: 55px; }
.panel-kicker { font-size: 17px; color: rgb(152, 129, 170); letter-spacing: 1px; display: block; margin-bottom: 20px; }
.answer-original > img { width: 100%; height: 330px; object-fit: cover; border: 1px solid rgba(255, 255, 255, 0.11); }
.answer-detail-strip { display: flex; justify-content: space-between; border-top: 1px solid rgba(255, 255, 255, 0.14); margin-top: 24px; padding-top: 19px; }
.answer-detail-strip > div { display: flex; gap: 17px; align-items: center; }
.answer-detail-strip span { font-size: 17px; color: rgb(151, 128, 170); }
.answer-detail-strip strong { font-size: 21px; font-weight: 400; color: rgb(196, 175, 215); }
#answer-diagram { height: 437px; }
.answer-bottom { position: absolute; left: 100px; right: 100px; top: 875px; display: flex; align-items: center; gap: 35px; border-top: 1px solid rgba(255, 255, 255, 0.133); padding-top: 27px; }
.answer-bottom > div { display: flex; align-items: center; gap: 18px; }
.reading-number { width: 44px; height: 44px; border: 1px solid rgb(107, 84, 125); display: grid; place-items: center; border-radius: 50%; font-size: 23px; color: rgb(188, 150, 218); }
.answer-bottom strong { font-size: 24px; font-weight: 400; display: block; color: rgb(227, 215, 238); }
.answer-bottom small { font-size: 17px; color: rgb(155, 131, 173); display: block; margin-top: 8px; }
.answer-bottom > i { color: rgb(114, 91, 131); font-size: 26px; margin: 0px 25px; }
.answer-bottom .wave-description { margin-left: auto; gap: 25px; }
.wave { display: flex; align-items: center; gap: 4px; height: 50px; width: 95px; }
.wave i { width: 4px; height: 12px; background: rgb(186, 140, 233); border-radius: 3px; }
.wave i:nth-child(3n) { height: 30px; background: rgb(255, 209, 42); }
.wave i:nth-child(4n) { height: 42px; }
.wave i:nth-child(5n) { height: 22px; }
.color-stages { position: absolute; left: 100px; right: 100px; top: 351px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 52px; }
.color-stages article { position: relative; }
.color-state-title { display: flex; align-items: center; gap: 17px; margin-bottom: 20px; }
.color-state-title em { font-family: Georgia, serif; font-size: 26px; color: rgb(178, 147, 194); }
.color-state-title h3 { font-size: 27px; font-weight: 500; }
.color-lens { height: 232px; position: relative; overflow: hidden; background: rgb(14, 7, 23); }
.color-lens img { width: 100%; height: 100%; object-fit: cover; transform: scale(1.13); }
.color-lens > span { position: absolute; bottom: 14px; left: 14px; background: rgba(21, 12, 35, 0.83); padding: 6px 10px; font-size: 16px; color: rgb(224, 200, 246); }
.color-schematic { height: 114px; background: rgb(238, 233, 242); margin-top: 13px; }
.color-stages article > p { font-size: 23px; line-height: 1.7; margin-top: 19px; color: rgb(132, 108, 146); }
.palette-ruler { position: absolute; left: 100px; right: 100px; top: 891px; height: 75px; display: flex; align-items: center; gap: 43px; border-top: 1px solid var(--rule); padding-top: 22px; }
.palette-ruler > div { display: flex; gap: 13px; align-items: center; font-size: 20px; }
.palette-ruler i { width: 35px; height: 35px; background: var(--swatch); border-radius: 50%; border: 1px solid rgba(0, 0, 0, 0.07); }
.palette-ruler code { font-size: 16px; color: rgb(139, 123, 150); letter-spacing: 0.5px; }
.palette-ruler > p { margin-left: auto; font-size: 17px; color: rgb(105, 83, 118); line-height: 1.65; }
.palette-ruler small { font-size: 15px; color: rgb(160, 141, 174); }
.language-layout { position: absolute; left: 100px; right: 100px; top: 355px; display: grid; grid-template-columns: 735px 1fr; gap: 65px; }
.visual-pair { display: grid; grid-template-columns: 1fr 33px 1fr; gap: 15px; }
.visual-pair img { width: 100%; height: 174px; object-fit: cover; display: block; background: rgb(9, 6, 16); }
.visual-pair > span { align-self: center; text-align: center; color: rgb(172, 144, 188); font-size: 25px; }
.visual-pair figcaption { font-size: 24px; margin-top: 15px; display: flex; align-items: center; justify-content: space-between; }
.visual-pair figcaption span { font-size: 16px; color: rgb(161, 139, 173); }
#morph-diagram { height: 168px; margin-top: 12px; }
.language-keys { display: flex; gap: 14px; justify-content: center; }
.language-keys > span { border: 1px solid rgb(212, 196, 223); color: rgb(138, 99, 158); font-size: 17px; padding: 7px 19px; }
.version-evidence { display: flex; gap: 26px; border-top: 1px solid rgb(220, 208, 229); margin-top: 30px; padding-top: 22px; font-size: 18px; line-height: 1.85; color: rgb(149, 121, 166); }
.version-evidence > span { font-size: 16px; color: rgb(174, 149, 187); }
.version-evidence b { font-weight: 400; color: rgb(108, 68, 127); margin-right: 18px; }
.space-application { position: relative; }
.space-application > img { width: 100%; height: 494px; object-fit: cover; object-position: 52% center; display: block; }
.space-application figcaption { margin-top: 21px; display: flex; gap: 23px; align-items: center; }
.space-application figcaption span { color: rgb(171, 147, 183); font-size: 16px; }
.space-application figcaption strong { font-size: 22px; font-weight: 400; color: rgb(109, 79, 123); }
.space-pin { position: absolute; font-size: 16px; color: rgb(244, 223, 255); border: 1px solid rgba(255, 255, 255, 0.467); border-radius: 20px; padding: 7px 13px; background: rgba(22, 11, 35, 0.733); }
.pin-wall { top: 155px; right: 103px; }
.pin-river { top: 368px; left: 50%; }
.closing-art { position: absolute; width: 1800px; height: 810px; right: -645px; top: 40px; object-fit: cover; }
.closing-veil { position: absolute; inset: 0px; background: linear-gradient(90deg, rgb(16, 13, 24) 0%, rgb(16, 13, 24) 30%, rgba(16, 13, 24, 0.85) 48%, rgba(16, 13, 24, 0) 84%), linear-gradient(0deg, rgb(16, 13, 24) 13%, rgba(16, 13, 24, 0) 53%); }
.closing-main { position: absolute; left: 100px; top: 155px; width: 1020px; }
.closing h2 { font-size: 70px; line-height: 1.4; margin-top: 24px; font-weight: 500; }
.closing-lead { font-size: 28px; line-height: 1.75; margin-top: 25px; color: rgb(198, 182, 210); }
.contributions { margin-top: 45px; display: flex; flex-direction: column; gap: 27px; }
.contributions > div { position: relative; padding-left: 58px; }
.contributions em { position: absolute; top: 0px; left: 0px; font-family: Georgia, serif; font-size: 27px; color: rgb(139, 100, 159); }
.contributions h3 { font-size: 27px; font-weight: 400; margin-bottom: 9px; }
.contributions p { font-size: 21px; color: rgb(154, 128, 173); line-height: 1.5; }
.closing-summary { position: absolute; left: 100px; top: 828px; }
.closing-summary > span { font-size: 17px; color: rgb(153, 129, 171); }
.closing-summary > p { font-size: 28px; margin-top: 17px; color: rgb(228, 209, 239); }
.closing-summary i { color: rgb(138, 90, 168); margin: 0px 18px; }
.closing-summary small { display: block; font-size: 19px; color: rgb(174, 151, 191); margin-top: 17px; }
.closing-status { position: absolute; right: 100px; top: 835px; text-align: right; }
.closing-status > span { font-size: 17px; color: rgb(173, 139, 187); border: 1px solid rgb(87, 52, 102); padding: 5px 12px; }
.closing-status p { font-size: 20px; color: rgb(171, 145, 191); line-height: 1.6; margin: 17px 0px 9px; }
.text-button { background: none; border: 0px; color: rgb(215, 181, 237); font-size: 17px; padding: 0px; text-decoration: underline; text-underline-offset: 5px; }
.viewer { position: fixed; bottom: 0px; width: 100%; height: 66px; background: rgb(250, 249, 252); display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 0px 24px; border-top: 1px solid rgb(217, 210, 226); z-index: 10; }
.viewer-brand { display: flex; align-items: center; gap: 10px; color: rgb(52, 38, 63); text-decoration: none; font-size: 14px; white-space: nowrap; }
.brand-ring { width: 15px; height: 15px; border: 1.5px solid rgb(124, 81, 166); border-radius: 50%; box-shadow: rgb(238, 229, 247) 0px 0px 0px 3px inset; }
.viewer-brand small { font-size: 11px; color: rgb(160, 138, 174); margin-left: 4px; }
.viewer-actions { display: flex; align-items: center; gap: 8px; }
.viewer button { border: 0px; border-radius: 3px; background: none; color: rgb(135, 112, 149); padding: 10px; font-size: 12px; }
.viewer button:hover { background: rgb(238, 230, 245); color: rgb(98, 31, 248); }
.viewer button.current { color: rgb(98, 31, 248); background: rgb(236, 227, 247); }
#chapters { display: flex; gap: 2px; }
#chapters button { font-size: 12px; padding: 10px 9px; }
#counter { font-size: 12px; color: rgb(160, 139, 174); white-space: nowrap; min-width: 48px; text-align: center; }
dialog { border: 1px solid rgb(224, 216, 231); border-radius: 8px; padding: 32px; color: rgb(52, 33, 63); background: rgb(248, 245, 251); width: min(900px, 90vw); max-height: 85vh; }
dialog::backdrop { background: rgba(14, 8, 29, 0.79); backdrop-filter: blur(7px); }
.dialog-top { display: flex; justify-content: space-between; align-items: center; color: rgb(154, 122, 170); font-size: 14px; border-bottom: 1px solid rgb(223, 209, 231); padding-bottom: 12px; }
.dialog-top button { font-size: 28px; background: none; border: 0px; color: rgb(143, 111, 159); }
.dialog-top + h2 { font-size: 29px; letter-spacing: 0px; margin: 28px 0px 15px; }
dialog > p { font-size: 16px; line-height: 1.8; color: rgb(150, 125, 165); }
.source-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 25px; margin-top: 28px; }
.source-grid h3 { font-size: 18px; font-weight: 500; margin-bottom: 12px; }
.source-grid p { font-size: 14px; line-height: 1.9; color: rgb(148, 118, 163); }


@media (prefers-reduced-motion: reduce) {
  * { animation: auto ease 0s 1 normal none running none !important; transition: none !important; scroll-behavior: auto !important; }
}
@media print {
  @page { size: 1920px 1080px; margin: 0px; }
  body { background: white; }
  #viewport { height: auto; display: block; overflow: visible; }
  #stage { height: auto; width: 1920px; transform: none !important; }
  .slide { position: relative; width: 1920px; height: 1080px; break-after: page; display: block !important; }
  .viewer, dialog { display: none !important; }
}

:host { --paper: #0b0812; --ink: #f5f1fb; --muted: #b8a9c8; --night: #0b0812; --rule: #352b43; }
body { background: rgb(5, 4, 10); color: var(--ink); }
